head.script:
scwin.init = function() {
    var data1 = [1, 1, 2, 4, 4, 4, 1, 1, 2, 4, 4, 4, 1, 3, 2, 4, 4, 5, 1, 3, 3, 5, 5, 5];
    dataList1.setData(data1);
    grid1.setData(data1);
}
scwin.radio2_onviewchange = function(info) {
    grid1.mergeCells(info.value);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. 샘플파일을 실행 후 bycol, bycolrec, byrow, byrowrec를 수행하여 merge를 확인한다.
    //1. Run the sample file and check the merge by performing bycol, bycolrec, byrow, and byrowrec.
    //Verify step 1. Merge works normally for row and col of same data.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('radio2_input_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_0').attr('rowspan') == '4'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_1').attr('rowspan') == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_2').attr('rowspan') == '3'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_3').attr('rowspan') == '3'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_4').attr('rowspan') == '3'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_5').attr('rowspan') == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_2_1').attr('rowspan') == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_5').attr('rowspan') == '2'", "true");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('radio2_input_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_0').attr('colspan') == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_1_0').attr('colspan') == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_3_1').attr('colspan') == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_3').attr('colspan') == '3'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_1_3').attr('colspan') == '3'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_2_3').attr('colspan') == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_3_3').attr('colspan') == '3'", "true");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('radio2_input_3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_0').attr('rowspan') == '4'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_1').attr('rowspan') == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_2').attr('rowspan') == '3'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_3').attr('rowspan') == '3'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_5').attr('rowspan') == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_2_1').attr('rowspan') == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_2_5').attr('rowspan') == '2'", "true");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('radio2_input_4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_0').attr('colspan') == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_0').attr('rowspan') == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_2_0').attr('rowspan') == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_2').attr('rowspan') == '3'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_3').attr('colspan') == '3'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_3').attr('rowspan') == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_2_3').attr('colspan') == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_2_3').attr('colspan') == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_3_1').attr('colspan') == '2'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
	scwin.init()
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 26-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
